  if (id === "d-democracy-01" || id === "d-democracy-02" || id === "n-power-01" || id === "n-power-02" || id === "n-power-03" || id === "n-democracy-01" || id === "n-democracy-02" || id === "n-democracy-03" || id === "n-hierarchy-02" || id === "p-democracy-02" || id === "p-democracy-03") return "source-dahl";
