  if (id.startsWith("d-ecology")) return "source-rockstrom";
  if (layer === "descriptive" && domain === "Economy") return "source-hayek";
  if (layer === "descriptive" && domain === "Power") return "source-north";
  if (layer === "descriptive" && domain === "Democracy") return "source-dahl";
  if (layer === "descriptive" && domain === "Culture") return "source-schwartz";
