const AUTONOMIST_MARXISM_CONTEXT = "Analytical scope: Autonomist Marxism as a historically varied Marxist current centered on worker and social autonomy, self-activity, class composition, expanded social reproduction, anti-vanguard movement organization, decentralization as a principle, and practical control over time and collective activity; not Marxism or anti-capitalism in general, workplace democracy or horizontal style alone, Council Communism's council-constitutive route, Libertarian Socialism, Marxism-Leninism's party-state route, Socialist / Marxist Feminism's wider class-gender traditions, or any single contemporary movement.";
const AUSTROMARXISM_CONTEXT = "Analytical scope: Austromarxism as a historically specific and internally varied Austrian Marxist and Social Democratic current associated with Habsburg, Red Vienna, and First Austrian Republic contexts, historically contextualized Marxist analysis, worker-movement unity, democratic institutional strategy, socialist transformation, and personal or non-territorial national autonomy within a federated multinational order; preserve variation among Bauer, Renner, Adler, Hilferding, Neurath, reform and revolution, parliamentary, municipal, and associational practice, and national-autonomy interpretations; not Marxism or Social Democracy in general, Austrian identity, nationalism, multiculturalism, national autonomy alone, generic parliamentary reform, Marxism-Leninism, Communism, one historical regime, one theorist, or any single contemporary programme.";
const EGALITARIAN_LIBERAL_FEMINISM_CONTEXT = "Analytical scope: Egalitarian-Liberal Feminism as a family within liberal feminism conceiving freedom as personal and political autonomy and holding that autonomy and equal opportunity depend on enabling conditions, democratic inclusion, and public action against gendered institutional barriers; preserve variation over procedural and relational autonomy, substantive equality, family and care, anti-discrimination, affirmative action, welfare, public reason, and the role and limits of state power; not feminism, liberalism, formal rights or equality, public provision, anti-discrimination, care, or state action alone, nor Classical-Liberal Feminism's primarily noninterference and limited-state route, Social Liberalism without gendered autonomy and gender-system analysis, Marxist, Socialist, or Materialist Feminism's constitutive production and social-reproduction theory, Radical Feminism's constitutive structural-sexual domination account, or any single author or policy.";
const BUDDHIST_NATIONALISM_CONTEXT = "Analytical scope: Buddhist Nationalism as a variable religious-national political project in which Buddhist histories, institutions, symbols, or moral claims help define national identity, public order, membership, or self-determination; preserve variation across Sri Lankan, Myanmar, Thai, Tibetan, and other historical and jurisdictional contexts, monastic and lay authority, anti-colonial and defensive narratives, state patronage, minority boundaries, democratic contestation, and global or transnational pressures; not Buddhism or private faith, cultural familiarity, ordinary patriotism, generic Religious Nationalism, nationalism without Buddhist-national translation, one country, one monk, one minority conflict, one constitutional model, or any single contemporary party or programme.";
const CHRISTIAN_NATIONALISM_CONTEXT = "Analytical scope: Christian Nationalism as a heterogeneous religious-national political project joining Christian identity, narratives, institutions, or authority claims to national membership and public-institutional power, including varied theological, constitutional, democratic, populist, and authoritarian routes; preserve differences among Christian nationalisms, Christian Democracy, religious conservatism, civic religion, Christian patriotism, church establishment, integralism, dominionism, and one national case; not private Christian faith, ordinary patriotism, ceremonial religion, Christian social concern, generic Religious Nationalism, one party or current actor, one country, or one policy alone.";
const EGOIST_ANARCHISM_CONTEXT = "Analytical scope: Egoist Anarchism as a contested individualist-anarchist current associated with Stirnerian self-rule or ownness, resistance to imposed identities and compulsory authority, and voluntary association without absorption into a fixed collective; preserve debate over psychological, ethical, and self-relational readings of egoism, property and exchange, sociality, spontaneous cooperation, tactical political action, and the relation to Individualist Anarchism and libertarianism; not nonconformity, privacy, personal self-interest, selfishness, market libertarianism, Anarcho-Capitalism, anti-state sentiment alone, generic Anarchism, Nietzscheanism, or one interpretation of Stirner.";
const CULTURAL_FEMINISM_CONTEXT = "Analytical scope: Cultural Feminism as a contested feminist strand emphasizing gendered culture and experience, care, relationship, embodiment, and the political value of practices devalued by dominant institutions; preserve variation among historical difference-feminist, essentialist, anti-essentialist, relational, intersectional, postcolonial, and care-oriented readings and between cultural, institutional, and material mechanisms; not feminism or gender identity alone, care preference or care work alone, a claim that women share one fixed nature, one author's theory, Radical Feminism's constitutive patriarchy or sexual-domination account, Materialist Feminism's constitutive labor and material-social-relations account, Lesbian Feminism's constitutive compulsory-heterosexuality critique, or any single policy, community, or historical school.";
const CULTURAL_NATIONALISM_CONTEXT = "Analytical scope: Cultural Nationalism as a contested nationalist project of forming, preserving, and renewing a national community through language, memory, arts, education, symbols, heritage, and cultural associations, including projects that precede or exceed direct state control; preserve variation over civic and ethnocultural membership, regional and minority pluralism, state and non-state institutions, cultural revival and reinterpretation, historical and postcolonial contexts, and relation to religious, anti-colonial, and other nationalisms; not cultural pride, language use, ancestry, patriotism, citizenship, civic institutions, generic Nationalism, one fixed cultural essence, one state, one party, one heritage practice, or one author alone.";
const ETHNOCULTURAL_NATIONALISM_CONTEXT = "Analytical scope: Ethnocultural Nationalism as a contested nationalist conception that makes shared descent, inherited cultural continuity, language, customs, or ethnocultural membership constitutive of national community or political membership; preserve non-racial and racialized variation, mixed civic and ethnocultural forms, regional and minority pluralism, state and non-state institutions, historical and postcolonial contexts, and relation to cultural, civic, religious, conservative, anti-colonial, and racial nationalisms; not cultural pride, language use, ancestry identity, patriotism, immigration concern, religious identity, racial hierarchy alone, citizenship law alone, one policy, one state, or one author.";
const LESBIAN_FEMINISM_CONTEXT = "Analytical scope: Lesbian Feminism as a contested feminist current treating compulsory heterosexuality and gendered sexuality institutions as constitutive sources of women's subordination and linking lesbian autonomy, self-definition, community-building, and/or alternative institutions to feminist transformation; preserve race, class, disability, religious, trans, queer, bisexual, coalition, separatist, sex-positive, historical, and contemporary variation; not lesbian identity, sexual orientation, same-sex relationship, feminist identity, anti-men sentiment, sexuality rights alone, generic Radical/Cultural/Black Feminism, one separatist community, one author, or one policy.";
const ONE_NATION_CONSERVATISM_CONTEXT = "Analytical scope: One-Nation Conservatism as a historically situated and internally varied conservative tradition joining an organic national society, cross-class social cohesion, responsible inherited institutions, and constructive or gradual public reform; preserve Disraelian, interwar, postwar, and contemporary variation, paternalist and libertarian tensions, market and welfare variation, constitutional and democratic commitments, and disagreements over nationhood, sovereignty, immigration, and cosmopolitanism; not patriotism, welfare support, tradition, current party affiliation, one policy, or one historical leader alone.";
const ZIONISM_CONTEXT = "Analytical scope: Zionism as a historically situated and internally varied modern Jewish nationalist tradition centered on Jewish collective self-determination, political community, cultural or institutional revival, and contested relationships among homeland, sovereignty, diaspora, and the people living under resulting institutions; preserve political, cultural, labor/socialist, revisionist, religious, liberal, diasporic, multinational, autonomy, and post-state or post-independence variation, equal-citizenship and minority-rights disputes, and historical and jurisdictional context; not Jewish identity or religious practice, support for or opposition to a current government, one territorial programme, one party, one leader, one policy, antisemitism or anti-Palestinian sentiment alone, or current conflict opinion alone.";
const KHOMEINISM_CONTEXT = "Analytical scope: Khomeinism as a historically situated and internally contested Iranian Shi'i Islamist political formation associated with Khomeini's revolutionary interpretation of Islamic governance, clerical or jurist authority, anti-monarchical and anti-imperial independence, appeal to the oppressed, and state-building through an Islamic Republic; preserve variation between pre-revolutionary theory and post-revolutionary institutional practice, democratic or constitutional and authoritarian interpretations, populist and clerical registers, national and transnational scope, and critiques within Shi'i thought; not Shi'i identity or private faith, generic Islamism, anti-imperialism, social-justice concern, opposition to monarchy, support for or opposition to a present Iranian government or foreign policy, one leader's entire record, or operational militancy.";
const QUTBISM_CONTEXT = "Analytical scope: Qutbism as a historically situated and internally contested Egyptian Islamist intellectual and political current associated with Sayyid Qutb's accounts of divine sovereignty, jahiliyya, comprehensive Islamic moral order, disciplined transformative community, and revolutionary or reformist reconstitution; preserve variation across Qutb's intellectual periods, literary and theological registers, prison and post-prison writings, organizational settings, interpretations of authority and pluralism, and later reception; not Muslim identity or private faith, generic Islamism, generic religious conservatism, anti-Western sentiment, support for or opposition to the Muslim Brotherhood, Salafi-Jihadism or al-Qaeda membership, operational militancy, current regime or policy opinion, or one reading of Qutb.";
const RADICAL_REPUBLICANISM_CONTEXT = "Analytical scope: Radical Republicanism as a plural historical and contemporary republican current emphasizing popular sovereignty, freedom as non-domination, equal civic standing, anti-corruption, continuous contestation, and transformative public institutions; preserve variation between historical radical republican traditions, critical/neo-republican theory, labour and socialist readings, popular constitutionalism, civic virtue, material independence, and direct or representative democratic routes; not patriotism, generic anti-corruption, majoritarianism, historical Republicanism as a whole, Contemporary Neo-Republicanism as a whole, civic participation alone, Marxism alone, one author, one historical movement, or one institutional design.";
const MATERIALIST_SOCIALIST_ECOFEMINISM_CONTEXT = "Analytical scope: Materialist / Socialist Ecofeminism as a plural ecofeminist branch connecting capitalist and patriarchal political economy, paid and unpaid labor, social reproduction, resource control, and ecological degradation, with collective and democratic transformation routes; preserve variation among materialist ecofeminism, Marxist ecofeminism, feminist political ecology, social-reproduction analysis, intersectional and decolonial approaches, state, municipal, cooperative, and autonomous institutions, and reform or transformative strategy; not green policy, feminism, socialism, welfare support, public ownership, social reproduction language, or environmental concern alone, nor Cultural / Spiritual Ecofeminism's primarily cultural or spiritual mechanism, generic Ecosocialism, Materialist Feminism without the ecological connection, or any single theorist, policy, country, or institutional model.";
const ANARCHO_PACIFISM_CONTEXT = "Analytical scope: Anarcho-Pacifism as a historically varied anarchist current combining anti-domination and anti-hierarchy with serious opposition to war, militarism, and structural violence and a nonviolent or prefigurative transformation route; pacifism and nonviolence are related but not identical, and principled, pragmatic, religious, secular, radical, reformist, and self-defense positions vary; not personal quietism, opposition to one war, anti-state language alone, strategic nonviolence alone, or any single historical or religious tradition.";
const ANARCHO_PRIMITIVISM_CONTEXT = "Analytical scope: Anarcho-Primitivism as a contested anti-civilization current within or adjacent to Green Anarchism that diagnoses civilization, industrial scale, divisions of labour, domestication, and technical systems as sources of domination or ecological disconnection and favors radically decentralized, self-organized, ecologically bounded lifeways; preserve variation over anti-civilization versus primitivist labels, technology and appropriate-tech exceptions, Indigenous and decolonial critiques, agriculture and domestication, scale, community, and tactics; not environmentalism, Green Anarchism broadly, Social Ecology, Deep Ecology, Neo-Luddism, degrowth, localism, survivalism, romanticized Indigenous identity, anti-technology sentiment alone, or any single theorist's programme.";
const SOCIAL_ECOLOGY_CONTEXT = "Analytical scope: Social Ecology as a historically varied ecological and anti-hierarchical current explaining ecological domination through social hierarchy and pursuing ecological integrity, future-generational responsibility, and democratic municipal or federated self-government with accountable common provision; preserve variation over Bookchin's communalist formulation, contemporary municipalism, scale, coordination, state capacity, ownership, and ecological value; not environmental concern, municipal policy, localism, anti-authoritarianism, bioregionalism, Deep Ecology, Green Anarchism, Ecosocialism, Rojava or Bookchin identification alone, or any single historical implementation.";
const CULTURAL_SPIRITUAL_ECOFEMINISM_CONTEXT = "Analytical scope: Cultural / Spiritual Ecofeminism as a plural ecofeminist strand connecting gendered domination and ecological interdependence through cultural, spiritual, symbolic, or relational critique; preserve variation among religious and secular approaches, relational selves, critiques of culture/nature and other hierarchical dualisms, care and justice, cultural diversity, intersectional and decolonial cautions, and material versus symbolic mechanisms; not private spirituality, gender identity, environmental concern, woman–nature essentialism, one religion or goddess tradition, cultural nostalgia, generic Ecofeminism, Cultural Feminism, Materialist / Socialist Ecofeminism, Deep Ecology, anti-technology sentiment, or any single author, community, policy, or theological programme.";
const WOMANISM_CONTEXT = "Analytical scope: Womanism as a historically varied Black women-centered intellectual, ethical, theological, and political current concerned with interlocking racialized gender, class, sexual, and embodied domination, Black women's knowledge and self-definition, survival and wholeness of whole communities, relational responsibility, and material and spiritual transformation; preserve variation over Walker-derived womanism, womanist theology, secular and queer strands, Africana Womanism, relation to Black Feminism, men and family, and state, reformist, abolitionist, or community-led routes; not Black identity, religion, family care, intersectionality, social justice, or support for Black women alone.";
const CLASSICAL_LIBERAL_FEMINISM_CONTEXT = "Analytical scope: Classical-Liberal Feminism as a contested, branch-sensitive family within liberal feminism emphasizing equal individual rights, freedom from coercive interference, bodily and economic autonomy, non-paternalism, constitutional democracy, and generally limited public power; classical-liberal variants differ over whether patriarchal culture as well as law sustains oppression and over markets, public provision, and reform; not feminism, liberalism, libertarianism, market support, formal equality, or private-choice language alone, nor any single historical author or contemporary movement.";
const ANARCHISM_CONTEXT = "Analytical scope: Anarchism as a plural political family united by critique of centralized, hierarchical, and unjustified authority and by varied commitments to autonomy, mutual aid, voluntary association, and self-organization; distinguish it from anti-government sentiment, localism, personal independence, libertarianism, Social Anarchism, Individualist Anarchism, Mutualism, and any single anti-state, market, collectivist, communist, feminist, ecological, religious, or historical programme; preserve variation over authority, ownership, association, violence, reform, revolution, and institutional scale.";
const CONSERVATISM_CONTEXT = "Analytical scope: Conservatism as a plural political family emphasizing historically situated institutional knowledge, human fallibility, continuity, authority, prudence, and bounded change; preserve variation over moderate, reactionary, radical, national, religious, liberal, and New Right formations and over markets, welfare, democracy, hierarchy, and state capacity; not generic caution, age, status-quo preference, one religion, one party, anti-government sentiment, nationalism, or a single historical author.";
const ECOLOGISM_CONTEXT = "Analytical scope: Ecologism / Green Ideology as a plural political family giving ecological limits, human–nature relations, interdependence, ecological justice, and social or institutional transformation a constitutive role in political judgment; preserve variation over anthropocentric and ecocentric arguments, ecological law, grassroots democracy, decentralization, nonviolence, social justice, markets, ownership, state capacity, and local, national, and planetary coordination; not generic environmental concern, conservation, Deep Ecology, bioregionalism, Green Politics as a movement umbrella, Social Ecology, Ecosocialism, one policy, or any single philosophical or political tradition.";
const LIBERALISM_CONTEXT = "Analytical scope: Liberalism as a plural political family requiring justification of political authority and giving constitutive weight to liberty, rights, equal standing, pluralism, and contestable limits on public power; preserve variation over negative, positive, and republican liberty, classical and new liberalism, markets, welfare, constitutionalism, universalism, particularism, state capacity, and cosmopolitan or state-centered reach; not Classical Liberalism, Social Liberalism, Libertarianism, Neoliberalism, one market or welfare policy, one party, or any single philosophical formulation alone.";
const SOCIALISM_CONTEXT = "Analytical scope: Socialism as a plural political family defined in contrast with capitalist domination and concerned with social or democratic control of productive resources, equality, solidarity, freedom, democracy, and collective provision; preserve variation over Marxist, democratic, market-socialist, libertarian, reformist, revolutionary, centralized, decentralized, and ecological routes; not Marxism, Communism, Social Democracy, Democratic Socialism, one historical regime, one ownership policy, or statism alone.";
const NATIONALISM_CONTEXT = "Analytical scope: Nationalism as a plural political family giving nations, national membership, national self-determination, shared identity, or national continuity a constitutive role in political life; preserve variation over civic, liberal, ethnocultural, anti-colonial, religious, conservative, Arab, Pan-African, and other nationalist formations and over state, transnational, democratic, cultural, and internationalist routes; not patriotism, cultural pride, ordinary citizenship, one membership rule, one territorial programme, Fascism, or any single historical or contemporary movement.";
const REPUBLICANISM_CONTEXT = "Analytical scope: Republicanism as a plural political family spanning historical civic traditions and contemporary civic or neo-republican theories; preserve variation over civic virtue, participation, mixed government, rule of law, resistance to corruption, liberty as non-domination, accountable institutions, common goods, private and public power, sovereignty, and cross-border extension; historical and contemporary senses overlap but are not identical; not a political party, patriotism, generic anti-corruption, majoritarianism, constitutionalism alone, or one historical republic.";
const FEMINISM_CONTEXT = "Analytical scope: Feminism as a plural political family and intellectual movement seeking to understand and end gender-based domination; preserve variation over liberal, radical, socialist, Marxist, materialist, Black, intersectional, ecological, queer, transnational, decolonial, Indigenous, religious, secular, and democratic approaches and over autonomy, equality, care, social reproduction, embodiment, identity, and institutional transformation; not formal equality alone, one account of patriarchy, one identity, one policy, one branch, or one historical movement.";
const ANARCHO_SYNDICALISM_CONTEXT = "Analytical scope: Anarcho-Syndicalism as a historically varied social-anarchist and syndicalist current joining worker-led organization, workplace self-government, direct action, and federated transformation; preserve variation over revolutionary and reformist strategy, union form, transnational development, violence and nonviolence, and the relation between anarchist principles and syndicalist practice; direct action here is a contested repertoire that is not synonymous with violence; not union membership, labor solidarity, co-determination, anti-state sentiment, worker consultation, Guild Socialism, National-Syndicalism, or one historical movement alone.";
const ANARCHO_CAPITALISM_CONTEXT = "Analytical scope: Anarcho-Capitalism as a contested market-anarchist current joining rejection of territorial state monopoly with strong private-property and contract claims, voluntary market coordination, and polycentric proprietary or protective institutions; preserve variation over Rothbardian and other market-anarchist arguments, property acquisition, inequality, legal and security provision, exit, institutional feasibility, and the disputed relation to anarchism; not generic libertarianism, small-government preference, anti-state sentiment, non-market anarchism, Mutualism, Minarchism, Right-Libertarianism, or one theorist's full programme.";
const ANARCHO_COMMUNISM_CONTEXT = "Analytical scope: Anarcho-Communism as a historically varied social-anarchist communist current joining anti-hierarchical and anti-state organization with abolition of capitalist ownership, decentralized common provision, free association, and need-oriented distribution; distinguish it from Collectivist Anarchism's historically bounded labor-contribution and remuneration debates, Social Anarchism's wider economic variation, Anarcho-Syndicalism's worker-union route, state-centered Communism, and Mutualism or market anarchism; preserve variation over revolutionary and reformist strategy, communal scale, voluntary association, and self-defense; not anti-government sentiment, equality alone, communal cooperation, public ownership, or any single author or period.";
const COLLECTIVIST_ANARCHISM_CONTEXT = "Analytical scope: Collectivist Anarchism as a historically bounded social-anarchist current associated especially with Bakunin and the First International, joining abolition of capitalist private ownership and state rule with collective control, free association, federated organization, and historically debated labor-linked distribution or remuneration; distinguish it from Anarcho-Communism's need-oriented communist route, Social Anarchism's wider economic variation, Anarcho-Syndicalism's worker-union route, Mutualism, and state-centered socialism; preserve variation over transition, labor accounting, communal scale, revolutionary strategy, gender, and international scope; not collective ownership alone, anti-government sentiment, generic worker control, union support, or a single author's full programme.";

